        l.toLowerCase().includes("resort") ||
        l.toLowerCase().includes("destination")
      );

      return {
        snippetHeadline: snippet.split("\n").slice(0, 15).join(" | "),
        rates: rates.slice(0, 8),
        feeLines: feeLines.slice(0, 5)
      };
    }, name);

    results.push({ name, ...paneData });
