const tabId = 725789690;

const results = await browserjs(tabId, () => {
  // Let's find all hotel cards
  const cards = Array.from(document.querySelectorAll("c-wiz[data-entity-id], div[data-id], div[jscontroller]"))
    .filter(el => el.querySelector("h2"));

  const extracted = [];
  const seen = new Set();

  for (const card of cards) {
    const h2 = card.querySelector("h2");
    if (!h2) continue;
    const name = h2.innerText.trim();
    if (!name || seen.has(name)) continue;
    seen.add(name);

    // Find price text
    const text = card.innerText;
    // Extract price ($...)
    const priceMatch = text.match(/\$([0-9,]+)/);
    const price = priceMatch ? priceMatch[0] : null;

    // Extract star rating
    const starMatch = text.match(/([0-9](\.[0-9])?)-star/i);
    const star = starMatch ? starMatch[0] : null;

    // Extract review rating
    const reviewMatch = text.match(/\b([3-5]\.[0-9])\b/);
    const review = reviewMatch ? reviewMatch[0] : null;

    // Extract location / neighborhood cues or snippets
    extracted.push({
      name,
      price,
      star,
      review,
      snippet: text.split("\n").slice(0, 8).join(" | ")
    });
  }
  return extracted;
});

console.log("Total unique hotel cards found:", results.length);
console.log(JSON.stringify(results, null, 2));

