const candidates = [
  // Central Park South / Central Park
  { name: "The Plaza", query: "The Plaza New York", area: "Central Park South" },
  { name: "The Ritz-Carlton New York, Central Park", query: "The Ritz-Carlton New York, Central Park", area: "Central Park South" },
  { name: "Mandarin Oriental, New York", query: "Mandarin Oriental New York", area: "Central Park / Columbus Circle" },
  { name: "JW Marriott Essex House New York", query: "JW Marriott Essex House New York", area: "Central Park South" },

  // Midtown / Fifth Avenue
  { name: "Aman New York", query: "Aman New York", area: "Midtown / Fifth Avenue" },
  { name: "The St. Regis New York", query: "The St. Regis New York", area: "Midtown / Fifth Avenue" },
  { name: "Baccarat Hotel New York", query: "Baccarat Hotel New York", area: "Midtown / Fifth Avenue" },
  { name: "The Langham, New York, Fifth Avenue", query: "The Langham New York Fifth Avenue", area: "Midtown / Fifth Avenue" },

  // Downtown / Tribeca / SoHo
  { name: "Four Seasons Hotel New York Downtown", query: "Four Seasons Hotel New York Downtown", area: "Downtown / Tribeca" },
  { name: "The Greenwich Hotel", query: "The Greenwich Hotel New York", area: "Downtown / Tribeca" },
  { name: "Crosby Street Hotel", query: "Crosby Street Hotel New York", area: "Downtown / SoHo" },
  { name: "The Mercer", query: "The Mercer Hotel New York", area: "Downtown / SoHo" },

  // Upper East Side / Madison Avenue
  { name: "The Carlyle, A Rosewood Hotel", query: "The Carlyle A Rosewood Hotel New York", area: "Upper East Side" },
  { name: "The Mark Hotel", query: "The Mark Hotel New York", area: "Upper East Side" },
  { name: "The Lowell", query: "The Lowell Hotel New York", area: "Upper East Side" }
];

const checkTab = (await tool.tabs_create({ url: "about:blank" })).details.tabId;
const results = [];

for (const cand of candidates) {
  const url = `https://www.google.com/travel/search?q=${encodeURIComponent(cand.query)}&dates=2026-10-15%2C2026-10-18`;
  await tool.navigate({ tabId: checkTab, url });
  try {
    await tool.wait_for({ tabId: checkTab, condition: "load_state", value: "load", timeout_ms: 10000 });
  } catch(e) {}

  // extract details from page
  const data = await browserjs(checkTab, () => {
    const text = document.body.innerText;

    // Find hotel name displayed
    const h1 = document.querySelector("h1")?.innerText || "";
    const h2s = Array.from(document.querySelectorAll("h2")).map(h => h.innerText);

    // Star rating
    const starMatch = text.match(/([0-9](\.[0-9])?)-star hotel/i);

    // Review score
    const scoreMatch = text.match(/\b([3-5]\.[0-9])\b\s*\([0-9.,]+[Kk]?\)/);

    // Main featured nightly price or headline price
    // Look for price near dates or "Oct 15 - 18"
    const priceMatches = Array.from(text.matchAll(/\$([0-9,]+)/g)).map(m => m[0]);

    // Look for fees mention (resort fee, destination fee, mandatory fee, taxes and fees)
    const feeMatch = text.match(/(resort fee|destination fee|facility fee|mandatory fee|taxes and fees)[^.\n]{0,100}/i);

    // Address
    const addressMatch = text.match(/[0-9]+\s+[A-Za-z0-9\s,.-]+,\s*New York,\s*NY\s*[0-9]{5}/);

    return {
      title: document.title,
      h1,
      topH2: h2s.slice(0, 3),
      star: starMatch ? starMatch[0] : null,
      score: scoreMatch ? scoreMatch[0] : null,
      firstPrices: priceMatches.slice(0, 5),
      feeSnippet: feeMatch ? feeMatch[0] : null,
      address: addressMatch ? addressMatch[0] : null,
      sampleText: text.slice(0, 600)
    };
  });

  results.push({ ...cand, ...data });
}

await tool.tabs_close({ tabId: checkTab });
console.log("Extracted candidates data count:", results.length);
console.log(JSON.stringify(results, null, 2));

