const tabId = 725789690;

// Let's check each hotel on tab 725789690 by clicking its card and reading the price/fee section
const hotelNames = [
  "The Plaza",
  "The Ritz-Carlton New York, Central Park",
  "Mandarin Oriental, New York",
  "JW Marriott Essex House New York",
  "Aman New York",
  "The Langham, New York, Fifth Avenue",
  "Waldorf Astoria New York",
  "Lotte New York Palace",
  "Four Seasons Hotel New York Downtown",
  "The Manner",
  "1 Hotel Central Park"
];

const results = [];

for (const name of hotelNames) {
  const info = await browserjs(tabId, (targetName) => {
    // Find card with h2 matching targetName
    const cards = Array.from(document.querySelectorAll("c-wiz[data-entity-id], div[data-id], div[jscontroller]"))
      .filter(el => el.querySelector("h2"));

    let targetCard = null;
    for (const card of cards) {
      const h2 = card.querySelector("h2");
      if (h2 && h2.innerText.includes(targetName)) {
        targetCard = card;
        break;
      }
    }

    if (!targetCard) return { found: false, name: targetName };

    // click targetCard
    const clickEl = targetCard.querySelector("a") || targetCard.querySelector("h2");
    clickEl.click();
    return { found: true, name: targetName };
  }, name);

  if (info.found) {
    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 1000 });

    // Extract side pane info
    const paneData = await browserjs(tabId, (targetName) => {
      const text = document.body.innerText;
      // find index of targetName after "New York"
      const idx = text.lastIndexOf(targetName);
      if (idx === -1) return { error: "not found in body" };
      const snippet = text.slice(idx, idx + 2500);

      // Look for rates and fees
      const rates = Array.from(snippet.matchAll(/\$([0-9,]+)/g)).map(m => m[0]);
      const feeLines = snippet.split("\n").filter(l => 
        l.toLowerCase().includes("fee") || 
        l.toLowerCase().includes("tax") || 
        l.toLowerCase().includes("nightly") ||
        l.toLowerCase().includes("resort") ||
        l.toLowerCase().includes("destination")
      );

      return {
        snippetHeadline: snippet.split("\n").slice(0, 15).join(" | "),
        rates: rates.slice(0, 8),
        feeLines: feeLines.slice(0, 5)
      };
    }, name);

    results.push({ name, ...paneData });
  }
}

console.log("Extracted pane data count:", results.length);
console.log(JSON.stringify(results, null, 2));

